uic:spaceOverviewPage.uic:css:
:uic-scope {
  --myne-slot-page-header-gap: 0.5rem;
  --myne-command-center-rail: 18rem;
  --myne-command-center-main: minmax(24rem, 1fr);
  background: linear-gradient(135deg, var(--myne-color-background), color-mix(in oklab, var(--myne-color-accent) 10%, var(--myne-color-background)));
}
:uic-region(activeRail) {
  background: color-mix(in oklab, var(--myne-color-panel) 88%, var(--myne-color-accent));
  border: 1px solid var(--myne-color-border);
  border-radius: var(--myne-radius-lg);
  padding: var(--myne-spacing-md);
  box-shadow: var(--myne-shadow-panel);
}
:uic-region(mainQueue) {
  background: var(--myne-color-panel);
  border: 1px solid var(--myne-color-border);
  border-radius: var(--myne-radius-lg);
  padding: var(--myne-spacing-md);
}
:uic-region(memoryRail) {
  background: color-mix(in oklab, var(--myne-color-panel) 92%, var(--myne-color-warning));
  border: 1px solid var(--myne-color-border);
  border-radius: var(--myne-radius-lg);
  padding: var(--myne-spacing-md);
}
